from common import *
B='54古屋奇影.txt'
make('huang_chengfang','黄成坊',B,
'黄成坊是拥有大厦与建筑业务的富豪，外表事业庞大，实际因不断扩张而周转不灵。他不愿承认经营已到危险边缘，花一年多策划把两亿元伪钞换成真钞的工程：利用有鬼传闻的林家古屋地下密室秘密印制，组织机械与其他技术专家从自己大厦地窖掘通银行保险库，再留下浓烟掩盖油墨和包装差异，使银行最初清点时误以为没有损失。他熟悉产业设备和人事安排，却仍将各位专家的技能当作组织资源使用，不是自己一个人完成所有机械工作。侄女无意提起安妮要去古屋过夜，使他急于阻止熟悉调查的主角介入，安排假事故和药酒拖延木兰花，反而把各处线索连在一起。对于大厦旧管理员死亡，他坚持说是对方本有心脏病而被吓死，责任不能只凭他的说辞归零，具体死法也不宜补成亲手开枪。木兰花诈称丁孟生已经出卖他，他才承认计划，得知同伙其实没有供述后情绪崩溃。他拒绝透露九名同伙去向，认为都是自己把他们拉下水。最终他无法承受成功形象破灭而自尽。其才干与悲剧同时存在，不能把结局写成成功者必然如此，更不能给财富失败附上无法抵抗的命运。',
'案情揭露后自尽，剩余巨款被搜出，九名同伙逃走。','建筑资源整合与精密犯罪策划','协调印刷、掘进、爆破和伪装人员，以真假钞替换利用银行信誉与清点盲点。','依赖设备、人员和长期准备；清理物证不能抹去气味与人际线索，极依赖成功形象。',[(1780,1838,'设备条件、业主与替换管理员。'),(1942,1948,'油墨残留。'),(2062,2114,'伪钞替换及烟的用途。'),(2234,2246,'侄女指认与资金困境。'),(2280,2384,'诈问、供述、死亡和赃款。')],
'维持不断成功的事业形象，用犯罪现金填补扩张造成的资金缺口。',[('经营出现难以承认的失败','有产业和专家可调动','设计迂回非法方案维持表面成功。'),('有人可能接近隐藏工程','担心调查者的能力','增设阻拦，却可能制造更多关联线索。'),('确信心腹已出卖自己','完美计划的自信崩塌','迅速失控；终局经历让后续演绎必须面对失败恐惧。')],roles=('反派',),scores=(1,0,2,3,2,3),tier='并',dead=True)
make('huang_huanfen','黄焕芬',B,
'黄焕芬是安妮的一年级大学同学，住在富裕叔叔黄成坊家里，性格活泼爽直。她从叔叔谈话中听到林家古屋闹鬼的故事，又在同学闲谈时提起，引发安妮想证明独立勇气的赌约。她并不知道叔叔已经利用古屋掩藏犯罪，还把打赌的事告诉他，意外成为他调整阻拦计划的信息来源。事件发生后，她与同学担心安妮并去报警；木兰花到校单独找她时，她先兴奋地想叫所有同学来见名人，听到话题转为叔叔与重案的关系，才陷入惊讶和痛苦。她没有为了保护亲人便否认所见，而是区分自己知道与不知道的部分，回忆两次关于古屋的谈话，并从画像中认出与叔叔会面的人是丁孟生。指认时她流泪，仍配合调查，说明其坦率能够在亲情压力下维持。叔叔自尽后，她明显消瘦，却未完全失去生活来源：生日时已获赠一幢大屋，租给外国领事便可维持生活。她最后向木兰花追问叔叔为何非死不可，对所谓卓越才干只报以苦涩。终局卡不把她当作共犯或靠叔叔犯罪致富的主动参与者，也不因悲伤让她永远停在单一受害姿态。',
'协助指认后经历叔叔自尽，以既有赠屋租金维持生活，仍在消化亲人失败与死亡。','具体记忆与坦率作证','能回忆熟悉家庭谈话、辨认来客画像，并在情感压力下提供亲历信息。','不知道叔叔全案安排，无战斗或全知推理证据，亲情冲击会造成悲伤与犹疑。',[(1078,1094,'鬼屋话题来源及报警。'),(2162,2206,'性格、两次谈话和辨认准备。'),(2234,2250,'指认与情感反应。'),(2396,2418,'生活来源和终局对话。')],
'认真对待朋友的安危，也希望理解亲人的选择，尽量不以袒护替代事实。',[('朋友遭遇自己引出的危险','意识到闲谈带来的后果','愿报警和提供相关记忆。'),('调查指向亲近长辈','仍能确认亲眼所见','难过但作证，不补充自己不知道的部分。'),('亲人的事业形象突然崩塌','已经失去对方','追问为何不接受失败，寻找继续生活的方式。')],scores=(0,0,0,1,0,1),tier='纸')
make('ding_mengsheng','丁孟生',B,
'丁孟生是黄成坊总务处职员，也是九名技术犯罪同伙中被正文明确指出姓名的一人。他的正式职位为替换大厦管理人员提供了接口，黄成坊最初接受调查时把录用来历不明管理者的责任推给这个已经失踪的职员，试图切断自己与掘进银行保险库的联系。与此同时，丁孟生还直接参加阻拦木兰花前往林家古屋的行动：在北欧式房屋中以饮酒招待，使她喝下带安眠药的酒，后来在路边沉睡一夜，无法及时保护安妮。黄焕芬从画像中认出，他就是曾在叔叔书房听取鬼屋说法的人，这才把看似不相关的药酒事件、总务人事与富豪联系起来。他不是实际向警方投诚的人，木兰花关于他已经出卖老板的说法是诈问策略；黄成坊信以为真后自行承认，不能把那段对话当丁孟生本人的供词。案发后九名同伙各获五百万元并转移海外，侦查追到南美时款项已经被提走。他的专业是组织内的一环，群体拥有工程与印钞技术不等于每人都同样掌握全部技能。后续九金刚活动需按实际个人身份核对，不能把整容后每个匿名成员的招式都分配给他。',
'与九名同伙中的其余人员携分赃款逃往南美；后续九金刚终局另作同卡补证。','人事掩护与药酒阻拦','利用总务职位和私人会面帮助隐蔽部署，以招待方式拖延调查者。','药物依赖被摄入，身份可被熟人认出；没有独立继承全部工程专家能力的证据。',[(1334,1378,'药酒造成延误。'),(1858,1868,'总务职员与录用掩护。'),(2198,2246,'会面及画像指认。'),(2280,2314,'所谓出卖是诈问。'),(2382,2394,'九人分赃与逃往南美。')],
'以正当职位掩护技术犯罪，按照共同计划排除调查者干扰并取得分赃。',[('需要替换关键岗位人员','总务职位可以提供说辞','以日常人事运作掩护部署。'),('调查者要去秘密地点','能以普通招待接近','通过拖延与药物干预行动。'),('工程完成且风险增加','获得分赃与外逃路线','离开原身份，继续依赖同伙的隐蔽安排。')],roles=('反派',),scores=(1,0,1,2,1,2),tier='并')
make('jiujingang','九金刚',B,
'九金刚是九名固定成员形成的技术犯罪团体，最初与黄成坊合谋，在林家古屋地下室印出几乎乱真的钞票，再使用最新工程机械掘开银行保险库，把假钞与真钞对换。他们包括第一流机械工程师和不同领域的专家，技能在成员之间分工，不能把群体卡解释成单独一个人同时拥有九份专长。为保守地点秘密，他们借既有闹鬼传闻造成恐怖印象；安妮独宿古屋与木兰花赶去保护的消息打乱了计划，他们又以橡皮人制造道路事故、盗车、药酒和屋内异象阻拦两人。这些布置有效拖延调查，却也将原本隐蔽的印钞工程与银行事件连在一起。工程完成后，他们拆走机器、清理碎屑，以为没有留下痕迹，空气中残余的油墨味仍使主角找到关键。他们并没有因首领败露便立刻落网，黄成坊坚持不供出位置，九人各取五百万元后经瑞士转款南美，警方追查无果。团体后续自称九金刚并继续犯罪，需将后篇真实结局合入；此卡保存整体合作与装置机制，成员丁孟生另有个人卡，不能将群体人数与个人卡重复相加成十名战力。',
'古屋案后九人携款逃往南美，未在本书被捕；后续生命合同的实际终局另补。','分工工程、印钞与伪装犯罪','九人协同操作专业机械、印刷及舞台式骗局，依靠长期准备在制度盲点完成盗换。','必须具备人员、时间、材料和隐蔽地点；不是单人力量，物证清理不消除气味或知情者记忆。',[(520,578,'掘进银行和烟雾装置。'),(1942,1948,'残留油墨。'),(2062,2114,'真假钞对换。'),(2234,2238,'道路与药酒参与者画像。'),(2382,2394,'人数、专家分工和外逃。')],
'以精密技术和合作证明能突破普通防范，分享巨额非法收益。',[('遇到依赖固定流程的目标','有长期工程准备条件','拆解防范环节，分工实施替换骗局。'),('旁观者接近秘密地点','能利用既有传闻和表演','制造恐怖或事故使其退避。'),('行动完成','仍可转移人员设备','清场分赃外逃，但可能忽略非实体痕迹。')],roles=('反派群体',),scores=(3,1,2,3,3,3),tier='强',uncertainties=['固定九人群体卡；丁孟生为其中一员，不能叠加计数。'])
cov(B,[('黄成坊','huang_chengfang','反派','伪钞工程主使与终局。'),('黄焕芬','huang_huanfen','单书主角','无意传讯、指认叔父同伙与身后反思。'),('丁孟生','ding_mengsheng','反派','具名核心成员，药酒与总务掩护。'),('九金刚','jiujingang','反派群体','固定九人技术作案团伙。'),('高翔','mulanhua_gao_xiang','系列主角','银行现场与富豪调查。'),('安妮','mulanhua_annie','系列主角','独宿古屋事件。'),('穆秀珍','mulanhua_mu_xiuzhen','系列主角','共同调查救援。'),('云四风','mulanhua_yun_sifeng','跨书重要配角','工程现场专业判断。'),('云五风','mulanhua_yun_wufeng','跨书重要配角','设备采购调查。'),('方局长','mulanhua_fang_director','跨书重要配角','指挥警务与银行协调。')],excluded=[('季元发／季之发','旧管理员受害者，死亡作为掩护人事变动的线索，无独立行动主线；原文有异写。'),('银行职员、杨科长、六名旧工人及其余同学','一次性协助与证人，无独立主角或反派身份；杨科长不凭称谓强合其他案件。')],notes=['丁孟生与九金刚群体属包含关系，不重复人数；九人实际姓名只公布给警方，正文未全列。','鬼屋异象服务于犯罪伪装，不建立有超能力的鬼魂卡。'])
